import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';
const root=process.cwd(),p='plans/260925-documentation-authority-unification/',r=p+'reports/phase-06/',s='/tmp/fgos-work/resume-truth/',read=f=>JSON.parse(fs.readFileSync(f)),write=(f,x)=>fs.writeFileSync(f,JSON.stringify(x,null,2)+'\n'),pin=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),label=process.argv[2]||'truth';
const gen=await import(path.join(root,'scripts/generate-doc-inventory.mjs')),g=await import(path.join(root,'scripts/check-doc-inventory-gates.mjs'));
const old=read(r+'working-identity-registry.json');fs.copyFileSync(r+'working-identity-registry.json',s+'identity-registry.json');
let registry=old;if(!gen.registryBindsToCommit(old.commit,pin,root)){console.log('Carry start',new Date().toISOString());registry=gen.carryForwardIdentityRegistryRepoWide(root,{commit:pin,identityRegistryPath:s+'identity-registry.json'});fs.writeFileSync(s+'identity-registry.json',JSON.stringify(registry)+'\n');console.log('Carried',JSON.stringify(registry.carryForward));}
console.log('Generate start',new Date().toISOString());const inv=gen.generateInventory(root,{commit:pin,identityRegistryPath:s+'identity-registry.json'});console.log('Generated',inv.items.length,inv.claimLedger.length,new Date().toISOString());
const bytes=fs.readFileSync(s+'identity-registry.json'),known=j=>['units','retiredUnits','identityGaps'].flatMap(k=>j[k]),ids=new Set(known(registry).map(u=>u.claimId));assert(known(old).every(u=>ids.has(u.claimId)));assert(bytes.length<90000000);const tuple=u=>JSON.stringify([u.claimId,u.sourcePath,u.sourceAnchor,u.sourceUnitDigest]);assert.deepEqual(inv.claimLedger.map(tuple).sort(),registry.units.map(tuple).sort());
const beforeIDs=new Set(known(old).map(u=>u.claimId)),oldLive=new Set(old.units.map(u=>u.claimId)),oldById=new Map(old.units.map(u=>[u.claimId,u]));write(s+label+'-native-accounting.json',{pin,carryForward:registry.carryForward,newUnits:registry.units.filter(u=>!beforeIDs.has(u.claimId)),changedUnits:registry.units.filter(u=>{const b=oldById.get(u.claimId);return b&&tuple(b)!==tuple(u)}),newGaps:registry.identityGaps.filter(u=>oldLive.has(u.claimId)),newRetired:registry.retiredUnits.filter(u=>oldLive.has(u.claimId)),ledger:inv.claimLedger.filter(u=>u.sourcePath.startsWith('docs/')),registryBytes:bytes.length});
const vocabulary=read(p+'claim-and-disposition-vocabulary.json'),droppedClaimsRegister=read(p+'dropped-claims-register.json'),decisions=[...g.loadDecisionShards(p+'pilot/decisions'),...g.loadDecisionShards(p+'ledger/decisions')],scope=read(r+'candidate-unverified-root-authorities.json').scope,ratchetResult=g.loadRatchetResult(root),runs=[];
for(const strict of [false,true])for(const prior of [p+'reports/identity-registry.json',p+'reports/phase-02-identity-registry.json']){console.log('Check',strict?'E':'D',prior,new Date().toISOString());const result=g.checkInventory({repoRoot:root,inventory:inv,vocabulary,identityRegistry:registry,droppedClaimsRegister,previousRegistries:[read(prior)],ratchetResult,strict,headCommit:pin,registryBytes:bytes,missingInputs:[],decisions,scope:strict?scope:null});write(s+label+'-'+(strict?'E':'D')+'-'+runs.length+'.json',result);runs.push({check:strict?'E':'D',prior,result});console.log('Result',result.fatalFindings.length,JSON.stringify(result.conservationOpen.map(x=>[x.type,x.count])));}
assert.deepEqual(runs[0].result,runs[1].result);assert.deepEqual(runs[2].result,runs[3].result);
write(s+label+'-proof.json',{pin,commands:['native carryForwardIdentityRegistryRepoWide','native generateInventory','native checkInventory both-prior D/E'],native:{items:inv.items.length,claims:inv.claimLedger.length,knownBefore:known(old).length,knownAfter:known(registry).length,zeroKnownIDLoss:true,activeTupleEquality:true,compactOneLine:true,bytes:bytes.length,SHA256:crypto.createHash('sha256').update(bytes).digest('hex')},bothPriorParsedEquality:true,runs,helperSource:fs.readFileSync(import.meta.filename,'utf8')});console.log('Done',new Date().toISOString());
